import random, math, json
mask32=(1<<32)-1
p=[]
for t in range(32):
 r=(t%4)*2; c=t//4
 p.extend([r*16+c,(r+1)*16+c,(r+8)*16+c,(r+9)*16+c,r*16+c+8,(r+1)*16+c+8,(r+8)*16+c+8,(r+9)*16+c+8])
assert sorted(p)==list(range(256))
inv=sorted(range(256),key=p.__getitem__)
assert [p[i] for i in inv]==list(range(256))
restored={}
for t in range(32):
 assert (t//2)*16+(t%2)*8==t*8
 if t&4: continue
 r=(t%4)*2; c=t//8
 for j in range(8):
  row=[r,r+1,r+8,r+9][j%4]; col=2*(c+(4 if j>=4 else 0))
  restored[row*16+col]=p[t*8+j]
  restored[row*16+col+1]=p[(t+4)*8+j]
assert restored==dict(enumerate(range(256)))
rng=random.Random(123)
def pack(values,bits):
 packed=[0]*(16*bits)
 for t in range(16):
  j=bits*t; k=32; buf=0
  for v in values[t*16:t*16+16]:
   k-=bits; buf|=(v&((1<<bits)-1))<<k; buf&=mask32
   if k<=16:
    packed[j]=(buf>>16)&65535; buf=(buf<<16)&mask32; k+=16; j+=1
 # SWAP16 on little-endian pairs makes earlier 16-bit word the high half.
 return [(packed[i]<<16)|packed[i+1] for i in range(0,len(packed),2)]
def fs(b,a,s):
 return ((((a<<32)|b)>>(s%32))&mask32) if s<32 else (a>>(s-32))
def chunk(ptr,bits,t,n,align=1):
 b0=(t+257)*bits-16; b2=b0+(n-1)*bits+16
 i0=b0//32; i2=(b2-1)//32; s=(i2+1)*32-b2
 a=ptr[i0%len(ptr)]; b=ptr[i2%len(ptr)]
 w=[0]*n
 for j in range(n-1,-1,-1):
  w[j]=fs(b,a,s+(n-1-j)*bits) if (n-1-j)%align==0 else w[j+1]>>bits
 return [x&65535 for x in w]
def dispatch(ptr,bits,t):
 if bits in (1,2,3): return chunk(ptr,bits,t,8,4 if bits<3 else 2)
 if bits==4:
  i=t//8; a=ptr[(i+31)%32]; b=ptr[i]; w2=fs(b,a,20)
  return [w2>>8&65535,w2>>4&65535,w2&65535,b>>16&65535,b>>12&65535,b>>8&65535,b>>4&65535,b&65535]
 n=2 if bits==7 else 4
 return sum([chunk(ptr,bits,t+i,n) for i in range(0,8,n)],[])
count=0
for bits in range(1,9):
 for trial in range(16):
  vals=[rng.randrange(1<<bits) for _ in range(256)]
  stream=''.join(format(x,'0%db'%bits) for x in vals)
  ptr=pack(vals,bits)
  assert ptr==[int(stream[i:i+32],2) for i in range(0,len(stream),32)]
  expected=[int(''.join(stream[j%len(stream)] for j in range((t+1)*bits-16,(t+1)*bits)),2) for t in range(256)]
  for t in range(0,256,8):
   assert dispatch(ptr,bits,t)==expected[t:t+8],(bits,t)
   count+=8
variants=[(16,16,128,3,1),(16,32,256,4,2),(16,32,128,4,2),(32,32,128,4,2),(64,16,128,4,2),(16,16,512,4,2)]
shared=[]
for m,k,n,s,f in variants:
 required=s*(2*m*k+2*(k//16)*(n//16)*16*8)+4*4*256
 assert required<=90*1024
 shared.append(required)
print(json.dumps({'permutation_bijection_and_inverse':256,'reconstruction_label_roundtrip':len(restored),'packed_windows_checked':count,'bitrates':list(range(1,9)),'max_bitrate_shared_bytes_variants_1_to_6':shared,'had_128_normalization':1/math.sqrt(128),'small_shape_example_max_slices':(128//32)*(128//128)//12},sort_keys=True))

